import UIKit

// Tiny offline reference fallback only. Full-resolution JPGs in the companion asset pack
// take precedence when imported into the app bundle. No network access or personal data.
enum PosterEmbeddedThumbnails {
    static func image(for name: String) -> UIImage? {
        let b64: String
        switch name {
        case "PosterConceptPalm": b64 = ""
        case "PosterConceptBazi": b64 = ""
        case "PosterConceptZiwei": b64 = ""
        case "PosterConceptPremium": b64 = ""
        default: return nil
        }
        guard let bytes = Data(base64Encoded: b64) else { return nil }
        return UIImage(data: bytes)
    }
}
